PRAGMA foreign_keys = ON;
CREATE TABLE checkout_quotes (id TEXT PRIMARY KEY, quote_hash TEXT NOT NULL UNIQUE CHECK(length(quote_hash)=64), chain TEXT NOT NULL CHECK(chain IN ('solana','sui')), network TEXT NOT NULL, wallet TEXT NOT NULL, payment_asset TEXT NOT NULL, payment_amount_atomic TEXT NOT NULL, receive_mint_or_type TEXT NOT NULL, receive_amount_atomic TEXT NOT NULL, treasury_address TEXT NOT NULL, service_fee_atomic TEXT NOT NULL, service_fee_recipient TEXT NOT NULL, nonce TEXT NOT NULL, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, price_source TEXT NOT NULL DEFAULT 'unknown', UNIQUE(wallet,nonce));
CREATE TABLE checkout_orders (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, quote_id TEXT NOT NULL REFERENCES checkout_quotes(id), quote_hash TEXT NOT NULL, wallet TEXT NOT NULL, chain TEXT NOT NULL, network TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('CREATED','QUOTED','AWAITING_SIGNATURE','SUBMITTED','CONFIRMING','EXECUTION_UNKNOWN','SETTLED','RECONCILED','RECEIPTED','EXPIRED','CANCELLED','FAILED','REJECTED')), intent_hash TEXT NOT NULL, transaction_base64 TEXT, last_valid_block_height INTEGER, transaction_id TEXT UNIQUE, submitted_at TEXT, block_or_checkpoint TEXT, verified_at TEXT, reconciled_at TEXT, receipt_id TEXT, last_rpc_error TEXT, reconciliation_attempts INTEGER NOT NULL DEFAULT 0, last_reconciled_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE checkout_transaction_intents (order_id TEXT PRIMARY KEY REFERENCES checkout_orders(id) ON DELETE CASCADE, quote_id TEXT NOT NULL REFERENCES checkout_quotes(id), quote_hash TEXT NOT NULL, intent_hash TEXT NOT NULL UNIQUE, chain TEXT NOT NULL, network TEXT NOT NULL, wallet TEXT NOT NULL, transfers_json TEXT NOT NULL, service_fee_atomic TEXT NOT NULL, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE checkout_rpc_observations (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL REFERENCES checkout_orders(id) ON DELETE CASCADE, provider_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('SETTLED','ABSENT','UNKNOWN','REJECTED')), transaction_id TEXT, block_or_checkpoint TEXT, reason TEXT, observed_at TEXT NOT NULL);
CREATE INDEX checkout_rpc_observations_order_idx ON checkout_rpc_observations(order_id, observed_at);
CREATE TABLE checkout_receipts (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES checkout_orders(id), quote_hash TEXT NOT NULL, intent_hash TEXT NOT NULL, transaction_id TEXT NOT NULL, evidence_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE rate_limit_buckets (key TEXT PRIMARY KEY, count INTEGER NOT NULL CHECK(count>=0), reset_at TEXT NOT NULL);
CREATE TABLE realtime_sessions (jti TEXT PRIMARY KEY, subject TEXT NOT NULL, topics_json TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
